"""Seed for the WO-8.3 golden auth app.

Creates the admin user from the per-run bootstrap credentials in the
environment (ADMIN_EMAIL / ADMIN_PASSWORD — generated by ProofDeploy
for this side and run, never committed), and creates an admin API
key the way the instance itself would: the key id and hex secret are
stored in the app's database, and the `<id>:<secret>` form is written
to the contract's declared key file, .pd-auth/admin_key, for the
host-side ghost_jwt provider to read after READY.
"""

import os
import secrets
import sqlite3
from pathlib import Path

conn = sqlite3.connect(os.environ.get("APP_DB", "app.db"))
email = os.environ.get("ADMIN_EMAIL", "")
password = os.environ.get("ADMIN_PASSWORD", "")
if email and password:
    conn.execute(
        "INSERT OR REPLACE INTO users (username, password) VALUES (?, ?)",
        (email, password),
    )
key_id = secrets.token_hex(12)
key_secret = secrets.token_hex(32)
conn.execute(
    "INSERT OR REPLACE INTO admin_keys (id, secret) VALUES (?, ?)",
    (key_id, key_secret),
)
conn.commit()
key_dir = Path(".pd-auth")
key_dir.mkdir(exist_ok=True)
(key_dir / "admin_key").write_text(f"{key_id}:{key_secret}\n", encoding="utf-8")
print("seeded")
